def test_thinking_true_starts_in_reasoning(self):
    cfg = deepseek_v4_config(thinking=True)
    assert cfg.initial_state.name == "REASONING"

def test_thinking_false_starts_in_content(self):
    cfg = deepseek_v4_config(thinking=False)
    assert cfg.initial_state.name == "CONTENT"

def test_parser_thinking_mode_matches_tokenizer_default(
    self, mock_tokenizer, chat_template_kwargs, expected_state
):
    parser = DeepSeekV4Parser(
        mock_tokenizer,
        chat_template_kwargs=chat_template_kwargs,
    )
    assert parser.parser_engine_config.initial_state.name == expected_state

def test_reasoning_effort_none_overrides_enable_thinking(self, mock_tokenizer):
    p = DeepSeekV4Parser(
        mock_tokenizer,
        chat_template_kwargs={
            "enable_thinking": True,
            "reasoning_effort": "none",
        },
    )
    assert p.parser_engine_config.initial_state.name == "CONTENT"

def test_reasoning_end_token_ids_drop_multi_token_tool_opener(
    self, thinking_parser
):
    # Like the real DeepSeek-V4 tokenizer, the mock vocab has no single
    # token for the DSML tool opener, so only </think> is tracked on the
    # token-ID fast path; the implicit tool-call exit still goes through
    # the text lexer.
    assert thinking_parser.reasoning_end_token_ids == {_THINK_END_ID}
    assert thinking_parser.find_reasoning_end([7, _THINK_END_ID, 8]) == (1, False)
    assert thinking_parser.find_reasoning_end([7, 8]) == (2, False)

def test_terminals_from_literals_still_works(self):
    literals = {"TOOL_START": "<tool_call>", "TOOL_END": "</tool_call>"}
    defs = terminals_from_literals(literals)
    assert len(defs) == 2
    names = {d.name for d in defs}
    assert names == {"TOOL_START", "TOOL_END"}
    for d in defs:
        assert d.is_literal
        assert d.literal in ("<tool_call>", "</tool_call>")

def test_terminal_literal_is_canonical_spelling(self):
    cfg = _alias_config()
    assert cfg.terminal_literal("TOOL_START") == "<tc>"
    assert cfg.terminal_literal("TOOL_END") == "</tc>"
    assert cfg.terminal_literal("MISSING") is None
    assert cfg.terminal_literals == {"<tc>", "<tcx>", "</tc>"}

def test_tool_call_as_implicit_end(self, parser):
    """Unpaired <tool_call> is implicit reasoning end."""
    assert parser.is_reasoning_end([_THINK_START_ID, 1, _TOOL_CALL_ID])

def test_prompt_tool_example_before_generation_think_not_end(self, parser):
    """Tool examples before the generation <think> must not end reasoning."""
    assert not parser.is_reasoning_end([_TOOL_CALL_ID, _TEXT_ID, _THINK_START_ID])

def test_completed_tool_call_after_open_think_is_end(self, parser):
    assert parser.is_reasoning_end(
        [_THINK_START_ID, 1, _TOOL_CALL_ID, 2, _TOOL_CALL_END_ID]
    )

def test_tool_call_after_think_end(self, parser):
    """<tool_call> after </think> — already ended."""
    assert parser.is_reasoning_end(
        [_THINK_START_ID, 1, _THINK_END_ID, _TOOL_CALL_ID]
    )

def test_is_reasoning_end(self, mock_tokenizer, ids, thinking, ended):
    parser = Qwen3Parser(
        mock_tokenizer, chat_template_kwargs={"enable_thinking": thinking}
    )
    assert parser.is_reasoning_end(ids) is ended

def test_wait_for_reasoning_follows_thinking(self, mock_tokenizer, thinking):
    parser = Qwen3Parser(
        mock_tokenizer, chat_template_kwargs={"enable_thinking": thinking}
    )
    assert parser.parser_engine_config.wait_for_reasoning is thinking

def test_injected_think_end_in_history_not_end(self, parser):
    assert not parser.is_reasoning_end(
        [_IM_START_ID, _TEXT_ID, _THINK_END_ID, _IM_END_ID, _IM_START_ID]
    )

def test_think_end_in_current_turn_is_end(self, parser):
    assert parser.is_reasoning_end(
        [_IM_START_ID, _TEXT_ID, _IM_END_ID, _IM_START_ID, _THINK_END_ID]
    )

def test_unpaired_tool_call_in_history_not_end(self, parser):
    assert not parser.is_reasoning_end(
        [_TOOL_CALL_ID, _TEXT_ID, _IM_END_ID, _IM_START_ID]
    )

def test_continued_turn_with_closed_thinking_is_end(self, parser):
    assert parser.is_reasoning_end(
        [_IM_START_ID, _THINK_START_ID, _TEXT_ID, _THINK_END_ID, _TEXT_ID]
    )

def test_empty_boundary_config_keeps_global_walk(self):
    """Configs without turn_boundary_tokens keep the pre-existing
    behavior: any </think> in the sequence ends reasoning."""
    cfg = qwen3_config(turn_boundary_tokens=frozenset())
    parser = Qwen3Parser(
        make_mock_tokenizer(_QWEN3_VOCAB), parser_engine_config=cfg
    )
    assert parser.is_reasoning_end(
        [_IM_START_ID, _TEXT_ID, _THINK_END_ID, _IM_END_ID, _IM_START_ID]
    )

def test_boundary_tokens_missing_from_vocab_keep_global_walk(self):
    """Boundary tokens absent from the vocabulary resolve to nothing,
    so subclasses reusing the default on a non-ChatML vocab keep the
    pre-existing behavior."""
    vocab = {
        token: token_id
        for token, token_id in _QWEN3_VOCAB.items()
        if not token.startswith("<|im_")
    }
    parser = Qwen3Parser(make_mock_tokenizer(vocab))
    assert parser.is_reasoning_end([_TEXT_ID, _THINK_END_ID, _TEXT_ID])

def test_boundary_with_thinking_disabled_is_end(self, mock_tokenizer):
    """With thinking disabled (initial state CONTENT) a walk that stops at a turn
    boundary must report reasoning as ended: the model never emits a marker."""
    parser = Qwen3Parser(
        mock_tokenizer, chat_template_kwargs={"enable_thinking": False}
    )
    assert parser.is_reasoning_end([_IM_START_ID, _TEXT_ID])

def test_thinking_disabled_initial_state_is_content(self, mock_tokenizer):
    p = Qwen3Parser(
        mock_tokenizer,
        chat_template_kwargs={"enable_thinking": False},
    )
    assert p.parser_engine_config.initial_state == ParserState.CONTENT

def test_thinking_enabled_initial_state_is_reasoning(self, mock_tokenizer):
    p = Qwen3Parser(
        mock_tokenizer,
        chat_template_kwargs={"enable_thinking": True},
    )
    assert p.parser_engine_config.initial_state == ParserState.REASONING

def test_default_initial_state_is_reasoning(self, mock_tokenizer):
    p = Qwen3Parser(mock_tokenizer)
    assert p.parser_engine_config.initial_state == ParserState.REASONING

def test_transform_dotted_mixed_string_rejected(self):
    template_spec = {
        "start_anchor": "<|assistant|>",
        "fields": {"x": {"open": "<x>", "close": "</x>", "transform": {"v": "pre {content.args}"}}},
    }
    with self.assertRaisesRegex(ValueError, "mixes"):
        parse_response("", template_spec, prefix="")

def test_join_validation(self):
    no_repeats = {"start_anchor": "a", "fields": {"x": {"open": "<x>", "close": "</x>", "join": ""}}}
    with self.assertRaisesRegex(ValueError, "requires 'repeats'"):
        parse_response("", no_repeats, prefix="")
    bad_type = {"start_anchor": "a", "fields": {"x": {"open": "<x>", "close": "</x>", "repeats": True, "join": 7}}}
    with self.assertRaisesRegex(ValueError, "must be a string"):
        parse_response("", bad_type, prefix="")

def test_optional_false_raises_when_missing(self):
    template_spec = {
        "defaults": {"role": "assistant"},
        "start_anchor": "<|assistant|>",
        "fields": {
            "content": {
                "open": "<response>",
                "close": "</response>",
                "content": "text",
                "optional": False,
            },
        },
    }
    with self.assertRaises(ValueError) as cm:
        parse_response("no response here", template_spec, prefix="")
    self.assertIn("content", str(cm.exception))

def test_unknown_content_parser_rejected(self):
    bad_template = {
        "defaults": {"role": "assistant"},
        "start_anchor": "<|assistant|>",
        "fields": {"x": {"open": "[", "close": "]", "content": "not-a-real-parser"}},
    }
    with self.assertRaises(ValueError) as cm:
        parse_response("[hi]", bad_template)
    self.assertIn("unknown content parser", str(cm.exception).lower())

def test_unsupported_version_rejected(self):
    bad_template = {
        "version": 2,
        "defaults": {"role": "assistant"},
        "start_anchor": "<|assistant|>",
        "fields": {"content": {"content": "text"}},
    }
    with self.assertRaises(ValueError) as cm:
        parse_response("hello", bad_template)
    self.assertIn("version", str(cm.exception).lower())

def test_two_implicit_fields_rejected(self):
    bad_template = {
        "defaults": {"role": "assistant"},
        "start_anchor": "<|assistant|>",
        "fields": {
            "a": {"content": "text"},
            "b": {"content": "text"},
        },
    }
    with self.assertRaises(ValueError):
        parse_response("hello", bad_template)

def test_transform_string_interpolation_rejected(self):
    bad_template = {
        "defaults": {"role": "assistant"},
        "start_anchor": "<|assistant|>",
        "fields": {
            "tool": {
                "open": "<tool>",
                "close": "</tool>",
                "content": "text",
                "transform": {"label": "name: {content}"},
            },
        },
    }
    with self.assertRaises(ValueError) as cm:
        parse_response("<tool>foo</tool>", bad_template)
    msg = str(cm.exception)
    self.assertIn("interpolation", msg)
    self.assertIn("{content}", msg)

def test_named_groups_without_transform_rejected(self):
    bad_template = {
        "defaults": {"role": "assistant"},
        "start_anchor": "<|assistant|>",
        "fields": {
            "tool": {
                "open_pattern": r"<tool name=(?P<name>\w+)>",
                "close": "</tool>",
                "content": "text",
            },
        },
    }
    with self.assertRaises(ValueError) as cm:
        parse_response("<tool name=foo>body</tool>", bad_template)
    msg = str(cm.exception)
    self.assertIn("transform", msg)
    self.assertIn("name", msg)

def test_prefix_is_required(self):
    spec = {
        "start_anchor": "<assistant>",
        "fields": {"content": {"content": "text"}},
    }
    with self.assertRaisesRegex(ValueError, "requires `prefix`"):
        ResponseParser(spec)
